import type { Db, Queryable, Row, SqlValue } from "./db";
import { register, UserError, type Context } from "./rpc";
import { insert, list, remove, seek, table, update, type Where } from "./tables";

/**
 * The CRUD pattern of WINDEV "Form" + "Table" windows (generated by the RAD or hand-written): the Table window lists
 * and deletes, the Form window opens one record in a mode (new / modify) and saves it. `defineCrud` registers
 * `<name>.list`, `<name>.get`, `<name>.save` and `<name>.delete` with the legacy checks, in the legacy order.
 *
 * Every user-visible text is a parameter: copy the legacy texts (Info/Error/YesNo calls, the WINDEV runtime's own
 * duplicate message in the language the legacy app ran with) from the evidence; never invent them.
 */
export interface CrudMessages {
  /** Shown (Info) when the record to open/delete no longer exists (HReadSeek fails after the list was read). */
  gone: string;
  /** The Table window's delete confirmation (YesNo/Confirm). The client asks it, then calls delete with confirmed. */
  confirmDelete: string;
  /** Refusal (Info) when the key item is empty. Omit when the legacy window did not check it. */
  emptyKey?: string;
  /**
   * The text of WINDEV's own duplicate error (HAdd/HModify fails on a unique key, HErrorDuplicates), shown with Error.
   * `item` = the key item, `value` = the duplicated value.
   */
  duplicate: (item: string, value: SqlValue) => string;
}

/** A dependent file that forbids the delete when it references the key (HReadSeekFirst(dep, column, key) found). */
export interface DeleteGuard {
  table: string;
  column: string;
  /** Legacy refusal text (Info). */
  message: string;
}

/** A refusal checked before the record is read (e.g. a reserved code that can never be deleted): text = Info, null = go on. */
export type PreDeleteGuard = (key: SqlValue, tx: Queryable) => Promise<string | null> | string | null;

export type CrudAction = "list" | "get" | "save" | "delete";
export type FormMode = "new" | "modify";

export interface CrudSpec {
  /** Procedure prefix, e.g. "brands" registers brands.list, brands.get, brands.save, brands.delete. */
  name: string;
  table: string;
  /** The business key item the windows search by (HReadSeek on it). */
  key: string;
  /** Items the Form window edits (its linked controls). Other columns keep their stored or default value. */
  fields: string[];
  messages: CrudMessages;
  /** Refusal (Info) of the Form window when, in new mode, HReadSeek finds the key already. */
  duplicateMessage: string;
  /** Extra checks on the key, in order (e.g. a forbidden character): the first that matches refuses with its text (Info). */
  keyRules?: { refuses: (key: SqlValue) => boolean; message: string }[];
  /** The rest of the Form window's checks before HAdd/HModify: return the refusal text (Info) or null. */
  validate?: (values: Row, mode: FormMode, tx: Queryable) => Promise<string | null> | string | null;
  /** Rights check per action (throw a UserError to refuse). Runs before anything else. */
  authorize?: (ctx: Context, action: CrudAction) => Promise<void> | void;
  preDeleteGuards?: PreDeleteGuard[];
  deleteGuards?: DeleteGuard[];
  /** This window's own delete confirmation, when it differs from `messages.confirmDelete`. */
  confirmMessage?: string;
  /** Table window order (default: the key). */
  orderBy?: string | string[];
  /**
   * HModify of a record another station deleted meanwhile: "refuse" (default) shows `messages.gone`; "reinsert" adds it
   * again (what the default WINDEV modification-conflict handling ends up doing when the user keeps their version).
   * Choose from the legacy evidence.
   */
  whenModifiedRecordIsGone?: "refuse" | "reinsert";
}

/** Postgres unique violation (23505), with the column when the driver reports it. */
export function isUniqueViolation(error: unknown): { column?: string } | null {
  const e = error as { code?: string; detail?: string; message?: string };
  if (e?.code !== "23505" && !/duplicate key|unique constraint/i.test(e?.message ?? "")) return null;
  const column = /Key \(([^)]+)\)/.exec(e.detail ?? e.message ?? "")?.[1];
  return { column };
}

export function defineCrud(spec: CrudSpec) {
  const t = table(spec.table);
  const key = spec.key.toLowerCase();
  const fields = spec.fields.map((f) => f.toLowerCase());
  const pick = (values: Row) => Object.fromEntries(Object.entries(values).filter(([f]) => fields.includes(f.toLowerCase()))) as Row;
  const keyOf = (values: Row) => Object.entries(values).find(([f]) => f.toLowerCase() === key)?.[1] ?? null;
  const authorize = async (ctx: Context, action: CrudAction) => spec.authorize?.(ctx, action);

  register({
    [`${spec.name}.list`]: async (ctx: Context, input: { where?: Where } = {}) => {
      await authorize(ctx, "list");
      return list(ctx.db, t.name, { where: input.where, orderBy: spec.orderBy ?? key });
    },
    [`${spec.name}.get`]: async (ctx: Context, input: { key: SqlValue }) => {
      await authorize(ctx, "get");
      return seek(ctx.db, t.name, { [key]: input.key });
    },
    [`${spec.name}.save`]: async (ctx: Context, input: { mode: FormMode; values: Row; id?: SqlValue }) => {
      await authorize(ctx, "save");
      const values = pick(input.values ?? {});
      const code = keyOf(values);
      if (spec.messages.emptyKey && String(code ?? "").trim() === "") throw new UserError(spec.messages.emptyKey);
      for (const rule of spec.keyRules ?? []) if (rule.refuses(code)) throw new UserError(rule.message);
      return ctx.db.transaction(async (tx: Db) => {
        if (input.mode === "new" && (await seek(tx, t.name, { [key]: code }))) throw new UserError(spec.duplicateMessage);
        const problem = await spec.validate?.(values, input.mode, tx);
        if (problem) throw new UserError(problem);
        try {
          if (input.mode === "new") return await insert(tx, t.name, values);
          // HModify of the record read at open (identified by its primary key).
          const stored = input.id === undefined ? null : await update(tx, t.name, input.id, values);
          if (stored) return stored;
          if (spec.whenModifiedRecordIsGone === "reinsert") return await insert(tx, t.name, values);
          throw new UserError(spec.messages.gone);
        } catch (error) {
          const duplicate = isUniqueViolation(error);
          if (duplicate) throw new UserError(spec.messages.duplicate(duplicate.column ?? key, code), "error");
          throw error;
        }
      });
    },
    [`${spec.name}.delete`]: async (ctx: Context, input: { key: SqlValue; confirmed?: boolean }) => {
      await authorize(ctx, "delete");
      return ctx.db.transaction(async (tx: Db) => {
        for (const guard of spec.preDeleteGuards ?? []) {
          const refusal = await guard(input.key, tx);
          if (refusal) throw new UserError(refusal);
        }
        const row = await seek(tx, t.name, { [key]: input.key });
        if (!row) throw new UserError(spec.messages.gone);
        for (const guard of spec.deleteGuards ?? [])
          if (await seek(tx, guard.table, { [guard.column]: input.key })) throw new UserError(guard.message);
        if (!input.confirmed) return { needsConfirmation: spec.confirmMessage ?? spec.messages.confirmDelete };
        await remove(tx, t.name, row[t.primary]);
        return { deleted: true };
      });
    },
  });
}
